struct IO{RecoverablePadExchange& q;SessionId session;unsigned mode,step=0,sends=0,observations=0;uint64_t clock=0;PartyBoardInputState state{0,123,4,5};Packet first{};
uint64_t now(){return clock;}PartyBoardInputState capture(){return state;}
bool send(const Packet&p){if(!sends)first=p;else assert(first==p);sends++;return true;}
void accepted(const PartyBoardInputState& captured,const PADStatus* pads){observations++;assert(observations==1&&captured.frame==0&&captured.checkpoint==123&&captured.frand==4&&captured.rand8==5);assert(pads[0].button==7&&pads[1].button==42);}
void wait(){clock++;}
bool pump(){step++;assert(step<10);if(mode==3){state.frand++;return true;}if(mode&&step==2){assert(q.disconnected(2,clock));assert(q.remainingRecoveryMs(clock)==60000);assert(q.remainingRecoveryMs(clock)==60000);}
if(mode==2&&step==3){clock=60001;assert(q.remainingRecoveryMs(clock)==0);return true;}
if(mode==4&&step==3){RecoverySession identity{"01"+std::string(30,'0'),std::string(64,'b'),std::string(64,'a'),"unlocked-no-save-v1",0,0,0,{{"host",0},{"guest1",1}}};auto report=nativePausedStateReport(identity,q.capture(2,0,{123,4,5},clock),"guest1",std::string(32,'c'));report["frame"]=1;report["inputFrame"]="1";report["checkpoint"]=124;std::array<uint8_t,44> merged{};merged[0]=7;merged[11]=42;merged[32]=255;merged[43]=255;nlohmann::ordered_json receipt{{"frame","0"},{"checkpoint",123},{"frand",4},{"rand8",5},{"pads",merged}};q.preparePausedReplay("guest1",std::string(32,'c'),report,receipt,2,0,{123,4,5},clock);return true;}if(step==3){if(mode==1){assert(q.remainingRecoveryMs(clock)==59999);assert(q.recovered(2,q.epoch(),q.revision(),clock));assert(q.resume(q.epoch(),q.revision(),clock));}Pad pad{};pad[0]=42;auto packet=encode({session,0,123,1,pad});assert(q.receive(2,packet)==Receive::Accepted);}return true;}};
struct AdvancingClockIO:IO {bool pump(){++clock;q.tick(clock);return IO::pump();}};
void verifyAdvancingPumpClock(){SessionId session{};session[0]=1;RecoverablePadExchange q(session,{1,2,0,0},1,{0,-1,-1,-1});RecoverySession identity{"01"+std::string(30,'0'),std::string(64,'b'),std::string(64,'a'),"unlocked-no-save-v1",0,0,0,{{"host",0},{"guest1",1}}};assert(q.bindOriginalSession(identity,"host","host"));AdvancingClockIO io{{q,session,0}};PADStatus pads[4]{};pads[0].button=7;assert(runNativeInputPoll(q,pads,io.state,io));assert(q.nextFrame()==1&&io.observations==1);}
int main(){verifyAdvancingPumpClock(); {NativeInputObservations trace; PADStatus pads[4]{}; pads[3].button=0x1234;pads[3].stickX=-7;pads[3].extButton=9;for(unsigned i=0;i<300;++i)trace.record({i,123,4,5},pads);assert(trace.acceptedCount()==300&&trace.entries().size()==256);assert(trace.entries()[255].state.frame==255&&trace.entries()[0].state.frame==0);const auto& bytes=trace.entries()[0].pads;assert(bytes[33]==0x34&&bytes[34]==0x12&&bytes[35]==uint8_t(-7));} {SessionId session{};session[0]=1;RecoverablePadExchange q(session,{1,2,0,0},1,{0,-1,-1,-1}); RecoverySession identity{"01"+std::string(30,'0'),std::string(64,'b'),std::string(64,'a'),"unlocked-no-save-v1",0,0,0,{{"host",0},{"guest1",1}}};assert(q.bindOriginalSession(identity,"host","host"));IO io{q,session,0};PADStatus pads[4]{};pads[0].button=7;io.state.frame=1;assert(!runNativeInputPoll(q,pads,io.state,io));assert(io.step==0&&io.sends==0&&q.nextFrame()==0&&pads[0].button==7);assert(q.tick(0)==ReconnectPolicy::State::ReturnToMenu);} for(unsigned mode=0;mode<5;mode++){SessionId session{};session[0]=1;RecoverablePadExchange q(session,{1,2,0,0},1,{0,-1,-1,-1});PADStatus pads[4]{};pads[0].button=7;IO io{q,session,mode};assert(!runNativeInputPoll(q,pads,io.state,io)&&io.step==0&&q.nextFrame()==0);RecoverySession identity{"01"+std::string(30,'0'),std::string(64,'b'),std::string(64,'a'),"unlocked-no-save-v1",0,0,0,{{"host",0},{"guest1",1}}};assert(q.bindOriginalSession(identity,"host","host"));NativeInputPollBinding<IO> binding(q,io); PartyBoardNativeInputExchange callback=&NativeInputPollBinding<IO>::sample; assert(!callback(nullptr,pads,&io.state)); assert(!callback(&binding,nullptr,&io.state)); assert(!callback(&binding,pads,nullptr)); bool ok=callback(&binding,pads,&io.state)==1;if(mode<2||mode==4){assert(ok&&q.nextFrame()==1&&pads[1].button==42);assert(io.sends==(mode==1?2:1)&&io.observations==1);assert(q.completedPoll()&&q.completedPoll()->frame==0&&q.completedPoll()->state.checkpoint==123&&q.completedPoll()->pads[11]==42&&q.completedPoll()->localPacketCount==1&&q.completedPoll()->localPackets[0]==io.first);;if(mode==4){assert(q.tick(io.clock)==ReconnectPolicy::State::Paused&&q.remainingRecoveryMs(io.clock)==59999);assert(q.begin(pads,{124,4,5},io.clock));assert(q.poll({124,4,5},pads,io.clock)==Exchange::Waiting);}}else assert(!q.completedPoll()&&io.observations==0&&!ok&&q.nextFrame()==0&&pads[0].button==7&&pads[1].button==0);}std::cout<<"PASS native retained poll normal/paused resend/deadline/state drift; synthetic coordinator only\n";}








